function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const grid = $('GET meetings values').first().json.values || [];
const vr = $('GET sheets').first().json.valueRanges || [];
const st = (vr[0] || {}).values || [];
const inv = (vr[1] || {}).values || [];
const pipe = (vr[2] || {}).values || [];
if (st.length < 40 || inv.length < 200 || pipe.length < 500) { throw new Error('ABORT: short read ' + st.length + '/' + inv.length + '/' + pipe.length); }

function isHdr(row) { return /startup got meetings/i.test(s((row || [])[1])) && /\d/.test(s((row || [])[0])); }
const hdrs = []; for (let i = 0; i < grid.length; i++) { if (isHdr(grid[i])) { hdrs.push(i); } }
if (!hdrs.length) { throw new Error('ABORT: no staircase blocks'); }
const TODAYD = new Date(Date.UTC(2026, 8, 15));
function blockDate(label) { const m = s(label).match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/); if (!m) { return null; }
  const a = +m[1], b = +m[2], y = +m[3]; const c = [];
  if (b >= 1 && b <= 12 && a >= 1 && a <= 31) { c.push(new Date(Date.UTC(y, b - 1, a))); }
  if (a >= 1 && a <= 12 && b >= 1 && b <= 31) { c.push(new Date(Date.UTC(y, a - 1, b))); }
  const past = c.filter(function (d) { return d <= TODAYD; }); const pool = past.length ? past : c;
  pool.sort(function (x, z) { return z - x; }); return pool[0] || null; }
let li = hdrs[hdrs.length - 1]; let ld = blockDate(s(grid[li][0]));
for (const i of hdrs) { const d = blockDate(s(grid[i][0])); if (d && (!ld || d > ld)) { ld = d; li = i; } }
const stair = {};
for (let i = li + 1; i < grid.length; i++) { const row = grid[i] || []; if (isHdr(row)) { break; }
  const m = s(row[1]).match(/^(\d+)\s*meetings?/i); if (!m) { if (Object.keys(stair).length) { break; } else { continue; } }
  const n = parseInt(m[1], 10);
  for (let j = 2; j < row.length; j++) { const nm = s(row[j]); if (!nm) { continue; } const k = nz(nm); if (stair[k] === undefined || n > stair[k]) { stair[k] = n; } } }
const ALIAS = { caffeinacoffee: 'caffenacoffee' };
function meetingsFor(name) { const k = nz(name); let best = null;
  for (const sk of Object.keys(stair)) { const kk = ALIAS[sk] || sk;
    const hit = kk === k || (kk.length >= 4 && k.length >= 4 && (kk.indexOf(k) === 0 || k.indexOf(kk) === 0));
    if (hit && (best === null || stair[sk] > best)) { best = stair[sk]; } }
  return best === null ? 0 : best; }

const TAGS = [
  ['health', /health|medtech|bio|clinic|pharma|life science|wellness|fitness|diagnost|hospital|patient|doctor/],
  ['fintech', /fintech|lending|insur|payment|banking|wealth|credit|financial|neobank/],
  ['saas', /saas|b2b|enterprise|software|platform|api|devtool|cloud|workflow|automation/],
  ['consumer', /consumer|d2c|b2c|retail|fmcg|food|beverage|fashion|beauty|apparel|coffee|restaurant|cafe|grocer|kitchen|snack|personal care/],
  ['deeptech', /deeptech|deep tech|\bai\b|artificial intelligence|\bml\b|robot|iot|semiconductor|space|drone|quantum|computer vision|hardware/],
  ['climate', /climate|clean|energy|solar|ev\b|electric vehicle|sustain|green|water|waste|carbon|recycl/],
  ['edtech', /edtech|education|learning|skill|training|exam|student|course/],
  ['logistics', /logistic|supply chain|mobility|delivery|freight|shipping|transport|warehous/],
  ['agritech', /agri|farm|agtech|crop/],
  ['hrtech', /hrtech|\bhr\b|recruit|talent|hiring|staffing|workforce/],
  ['proptech', /proptech|real estate|construction|coworking|interior|windoor|building/],
  ['media', /media|gaming|content|entertainment|creator|social|dating|travel|music|video/]
];
function tagsOf(txt) { const t = s(txt).toLowerCase(); const o = {}; for (const p of TAGS) { if (p[1].test(t)) { o[p[0]] = 1; } } return Object.keys(o); }

// CURRENT grader - the bare word "revenue" catches "Pre-revenue"
function stageOld(txt) { const t = s(txt).toLowerCase();
  if (/series[\s-]*[b-e]\b|growth|pre-?\s*ipo/.test(t)) { return 4; }
  if (/series[\s-]*a\b/.test(t)) { return 3; }
  if (/pilot|traction|early revenue|revenue|mvp|launched/.test(t)) { return 2; }
  if (/\bseed\b/.test(t.replace(/pre-?\s*seed/g, ''))) { return 1; }
  if (/pre-?\s*seed|ideation|concept|idea|prototype/.test(t)) { return 0; }
  return 1; }
// FIXED grader - pre-revenue / pre-launch / pre-monetisation / MVP tested FIRST
function stageNew(txt) { const t = s(txt).toLowerCase();
  if (/pre-?\s*revenue|pre-?\s*launch|pre-?\s*monetis|pre-?\s*monetiz/.test(t)) { return 0; }
  if (/pre-?\s*seed|ideation|concept|\bidea\b|prototype/.test(t)) { return 0; }
  if (/\bmvp\b/.test(t)) { return 1; }
  if (/series[\s-]*[b-e]\b|growth|pre-?\s*ipo/.test(t)) { return 4; }
  if (/series[\s-]*a\b/.test(t)) { return 3; }
  if (/pilot|traction|early revenue|revenue|launched/.test(t)) { return 2; }
  if (/\bseed\b/.test(t.replace(/pre-?\s*seed/g, ''))) { return 1; }
  return 1; }
function investorBand(txt) { const t = s(txt).toLowerCase(); const h = [];
  if (/pre-?\s*seed|preseed/.test(t)) { h.push(0); }
  if (/\bseed\b/.test(t.replace(/pre-?\s*seed/g, ''))) { h.push(1); }
  if (/pilot|traction|early|pre-?\s*series[\s-]*a/.test(t)) { h.push(2); }
  if (/series[\s-]*a\b/.test(t)) { h.push(3); }
  if (/series[\s-]*[b-e]\b|series[\s-]*a\s*[\/&,]\s*b|growth|late|pre-?\s*ipo|onwards|and above|private equity/.test(t)) { h.push(4); }
  if (!h.length) { return null; }
  return { lo: Math.min.apply(null, h), hi: Math.max.apply(null, h), seed: h.indexOf(1) >= 0 }; }
function chequeMin(txt) { const t = s(txt).replace(/,/g, '').toLowerCase(); if (!t) { return null; }
  const usd = /\$|usd/.test(t); const re = /(\d+(?:\.\d+)?)\s*(crores?|cr|million|mn|m|k|lakhs?|lacs?)?(?![a-z])/g;
  const tok = []; let m; while ((m = re.exec(t)) !== null) { tok.push({ v: parseFloat(m[1]), u: m[2] || '' }); }
  if (!tok.length) { return null; }
  for (let i = tok.length - 2; i >= 0; i--) { if (!tok[i].u && tok[i + 1].u) { tok[i].u = tok[i + 1].u; } }
  const vals = [];
  for (const k of tok) { const u = k.u || (usd ? 'm' : 'cr'); let cr;
    if (/^cr/.test(u)) { cr = k.v; } else if (/^la/.test(u)) { cr = k.v / 100; }
    else if (u === 'k') { cr = usd ? k.v * 0.0085 : k.v / 10000; } else { cr = usd ? k.v * 8.5 : k.v / 10; }
    if (cr > 0) { vals.push(cr); } }
  if (!vals.length) { return null; }
  if (vals.length === 1 && /up\s*to|upto|\bmax/.test(t)) { return 0; }
  return Math.min.apply(null, vals); }
function raiseOf(txt) { const t = s(txt).replace(/,/g, ''); if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*M/i); if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*K/i); if (m) { return parseFloat(m[1]) * 0.0085; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i); if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i); if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i); if (m) { return parseFloat(m[1]) / 100; }
  return null; }

const sh = (st[0] || []).map(s);
const S = {}; ['startup','owner','sector','stage','raise_inr_cr','active'].forEach(function (n) { S[n] = sh.indexOf(n); });
const ST = {}, changed = [];
for (let r = 1; r < st.length; r++) { const row = st[r] || []; const n = s(row[S.startup]); if (!n) { continue; }
  if (s(row[S.active]).toLowerCase() !== 'yes') { continue; }
  const oldG = stageOld(row[S.stage]), newG = stageNew(row[S.stage]);
  const mt = meetingsFor(n);
  ST[nz(n)] = { name: n, owner: s(row[S.owner]), tags: tagsOf(row[S.sector]), old: oldG, neu: newG, raise: raiseOf(row[S.raise_inr_cr]), meetings: mt, under5: mt < 5 };
  if (oldG !== newG) { changed.push([n, s(row[S.stage]), oldG, newG, mt]); } }

const ih = (inv[0] || []).map(s);
const II = {}; ['investor','email','sector','stage','cheque_inr_cr','do_not_contact'].forEach(function (n) { II[n] = ih.indexOf(n); });
const WRONG = {}; ['a2dventures','alphajwcventures','blacksoilcapitalformerlycaspiandebt','fuelventurefund','kemfinfamilyoffice','kaizenvest','tvscapitalfunds','northernarc','coinagesolutionsdebt','debtworksdebt','strideventures','innovencapital','capwise','epsilonxcapital'].forEach(function (k) { WRONG[k] = 1; });
const INV = {};
for (let r = 1; r < inv.length; r++) { const row = inv[r] || []; const n = s(row[II.investor]); if (!n) { continue; }
  const k = nz(n); if (WRONG[k]) { continue; }
  if (s(row[II.do_not_contact]).toLowerCase() === 'yes') { continue; }
  if (!s(row[II.email])) { continue; }
  const band = investorBand(row[II.stage]); if (!band) { continue; }
  if (INV[k]) { continue; }
  INV[k] = { name: n, email: s(row[II.email]).toLowerCase(), agnostic: /agno/i.test(s(row[II.sector])), tags: tagsOf(row[II.sector]), band: band, floor: chequeMin(row[II.cheque_inr_cr]) }; }

function passes(stp, b, grade) { let ov = false; for (const tg of b.tags) { if (stp.tags.indexOf(tg) >= 0) { ov = true; break; } }
  const sec = b.agnostic || ov;
  const chq = b.floor === null || (stp.raise !== null && stp.raise >= b.floor);
  let stage;
  if (grade >= b.band.lo && grade <= b.band.hi) { stage = 'in'; }
  else if (grade >= 3 && b.band.seed) { stage = 'in'; }
  else if (grade === b.band.lo - 1 || grade === b.band.hi + 1) { stage = 'adjacent'; }
  else { stage = 'off'; }
  return sec && chq && (stage === 'in' || (stp.under5 && stage === 'adjacent')); }

const ph = (pipe[0] || []).map(s);
const P = {}; ['deal_id','startup','investor','email','deal_shared','pause','next_due'].forEach(function (n) { P[n] = ph.indexOf(n); });
const changedKeys = {}; changed.forEach(function (c) { changedKeys[nz(c[0])] = 1; });
const wouldDrop = [], pairedInbox = {};
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || []; const sk = nz(row[P.startup]);
  const em = s(row[P.email]).split(/[,;\s]+/)[0].toLowerCase();
  if (em) { pairedInbox[sk + '|' + em] = 1; }
  if (!changedKeys[sk]) { continue; }
  if (s(row[P.deal_shared]).toLowerCase() === 'yes') { continue; }
  if (s(row[P.pause]).toLowerCase() === 'yes') { continue; }
  const stp = ST[sk]; const b = INV[nz(row[P.investor])]; if (!stp || !b) { continue; }
  const before = passes(stp, b, stp.old), after = passes(stp, b, stp.neu);
  if (before && !after) { wouldDrop.push([s(row[P.deal_id]), stp.name, s(row[P.investor]), s(row[P.next_due]), 'startup ' + stp.old + '->' + stp.neu + ', investor band ' + b.band.lo + '-' + b.band.hi]); } }

const wouldOpen = {}; let openTotal = 0;
for (const sk of Object.keys(changedKeys)) { const stp = ST[sk]; if (!stp) { continue; }
  const list = [];
  for (const ik of Object.keys(INV)) { const b = INV[ik];
    if (pairedInbox[sk + '|' + b.email]) { continue; }
    const before = passes(stp, b, stp.old), after = passes(stp, b, stp.neu);
    if (!before && after) { list.push(b.name); } }
  if (list.length) { wouldOpen[stp.name] = list; openTotal += list.length; } }

return [{ json: { startups_regraded: changed.length, regraded: changed,
  deals_that_would_drop: wouldDrop.length, drops: wouldDrop,
  new_matches_that_would_open: openTotal,
  opens_by_startup: Object.keys(wouldOpen).map(function (k) { return [k, wouldOpen[k].length, wouldOpen[k].slice(0, 12)]; }) } }];
